function NetworkBurstStructure = NetworkBurstStructure(NetworkBurstDetected, spikeTrain, netburst_member, units_participant, option_plot)

% function to analyze the temporal/spatial structure of network bursts 

opt_test = 2;

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   INPUTS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% structure array NetworkBurstDetection, generated by the funcion "NetworkBurstDetection", with the following field
%   .spikesBin(i,1):                total number of spikes in bin i
%   .time(i,1):                     midpoint of the bin i, in sec 
%   .nBurst:                        total number of network bursts
%   .IndivBurst(j).start            start point of network burst j, in sec
%   .IndivBurst(j).last             last point of network burst j, in sec
%   .IndivBurst(j).peak             peak point of network burst j, in sec
%   .IndivBurst(j).peakIdx:         peak point of network burst j
%   .IndivBurst(j).window:          temporal window to extract spike train from network burst j, in sec (revised October 2026: it was documented in ms)
%   .Channels(i,1):                 list of channels that robustly participate of network bursting     
%   .parameter                      structure with information about the network burst detection method
%   .timeStamp{j,i}                 time stamp of the spikes for the burst j coming from channel i (all channels), in msec

% netburst_member(i,1)              it indicates if the network burst event i is part of the analysis (=1) 
% units_participant(i,1)            index of units participating of the network bursting under analysis

% structure array NetworkBurstDetection, generated by the funcion "NetworkBurstDetection", with the following field
%   .spikesBin(i,1):                total number of spikes in bin i
%             (i,4):                midpoint of the bin i, in msec 
%   .nBurst:                        total number of network bursts
%   .IndivBurst(j).start            start point of network burst j, in ms
%   .IndivBurst(j).last             last point of network burst j, in ms
%   .IndivBurst(j).peak             peak point of network burst j, in ms
%   .IndivBurst(j).peakIdx:         peak point of network burst j
%   .IndivBurst(j).window:          temporal window to extract spike train from network burst j, in sec (revised October 2026: it was documented in ms)
%   .Channels(i,1):                 list of channels that robustly participate of network bursting     
%   .parameter                      structure with information about the network burst detection method
%   .timeStamp{j,i}                 time stamp of the spikes for the burst j coming from channel i (all channels), in msec

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   OUTPUT   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% ch: index of the neuron participating in network burst (from NetworkBurstDetected.Channels)

% NetworkBurstStructure.populationFiring{k}:             population firing rate of the burst k
%                                       (i,1):           (cumulative) total number of spikes in bin i
%                                       (i,2):           left side of the bin i, in msec
%                                       (i,3):           right side of the bin i, in msec
%                                       (i,4):           midpoint of the bin i, in msec
%                                       (i,5):           total number of active neurons in the bin i (absolute value)
% NetworkBurstStructure.neuronFiring(ch,i,1):            midpoint of the bin i, in msec
%                                   (ch,i,2):            total number of spikes in bin i for neuron ch (cumulative across all burst events)
%                                   (ch,i,3):            total number of bursts with activity in bin i for neuron ch
%                                   (revised October 2026: columns 2 and 3 are scaled to all the events: x nBurst/coverage(i))
% NetworkBurstStructure.coverage(i):                     number of events with data in the bin i (revised October 2026)
%                                   (ch,i,4):            number of spikes in bin i for neuron ch, normalized to the total number across all bins
%                                   (ch,i,5):            number of spikes in bin i for neuron ch, normalized to the peak value
% NetworkBurstStructure.structure(ch,1):                 order based on the onset (incremental order; nan if the neuron ch does not have a robust temporal structure)   
%                                (ch,2):                 onset of the activity for neuron ch, in ms (relative to the peak of the burst)
%                                (ch,3):                 peak of the activity for neuron ch, in ms (relative to the peak of the burst)
%                                (ch,4):                 tail of activity for neuron ch, in ms (relative to the peak of the burst)
% NetworkBurstStructure.mapPosition(ch,1):               position X of the neuron ch   
%                                  (ch,2):               position Y of the neuron ch
% NetworkBurstStructure.correlation:                     average correlation coefficient value

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%   PARAMETERS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

K_MSEC_SEC = 1/1000;                        % factor to rescale from msec to sec

BIN_SIZE_POP = 30;                          % bin size to analyze the population activity, in msec (default: 30)
BIN_NEURON = 10;                            % bin size to analyze individual neuron activity, in msec (10)

THRESHOLD_ACT = 0.4;                        % threshold to detect the onset; proportion of burst events with activity (0.4)
THRESHOLD_ACT_TWIN = 0.25;                  % threshold to detect the onset (backup option); proportion of burst events with activity across two consecutive bins (0.25)

THRESHOLD_TAIL = 0.25;                      % threshold to detect the tail; proportion of the peak firing rate (0.25)

MIN_BURST_PLOT = 3;
apply_parameters('NetworkBurstStructure');                                  % (revised October 2026) values of the parameter set of "run_pipeline", if any (see "pipeline_parameters")

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%     Population firing rate

nBurst = numel(find(netburst_member));
nPartNeu = numel(units_participant);

if nBurst>0 && nPartNeu>0

popFiring = cell(nBurst,1);
peak_burst = nan(nBurst,1);
left_burst = 0;
right_burst = 0;
idx_event = find(netburst_member);
for k=1:nBurst
    idx = idx_event(k);
    ini = NetworkBurstDetected.IndivBurst(idx).start/K_MSEC_SEC;            % start of the burst, in msec
    fin = NetworkBurstDetected.IndivBurst(idx).last/K_MSEC_SEC;             % end of the burst, in msec    
    n_bins = max(1, ceil((fin-ini)/BIN_SIZE_POP));                          % total number of bins to process the data (revised October 2026: at least 1)
    spikes = zeros(n_bins,5);                                               % matrix to save the binned data
        
    nextStart = ones(nPartNeu,1);

    for i=1:n_bins                                                          % across all bins
        aux_spikes = 0;
        aux_actCh = 0;
        spikes(i,2) = ini+(i-1)*BIN_SIZE_POP;                               % left side of the bin i, in msec
        spikes(i,3) = spikes(i,2) + BIN_SIZE_POP;                           % right side of the bin i, in msec
        spikes(i,4) = (spikes(i,2)+spikes(i,3))/2;                          % midpoint of the bin i, in msec
        
        for ch=1:nPartNeu
            idx_ch = units_participant(ch);                                 % index of the channel/neuron ch
            
            switch opt_test            
                case 1  % old method
                    aux1 = find(NetworkBurstDetected.timeStamp{idx,idx_ch} >= spikes(i,2));
                    aux2 = find(NetworkBurstDetected.timeStamp{idx,idx_ch} < spikes(i,3));
                    aux = intersect(aux1, aux2);                                    % index of all spikes of cluster ch within the bin i
                    spikes_total = numel(aux);
                    clear aux aux1 aux2
      
                case 2  % binnary search               
                    [spikes_total, ~, nextStart(ch)] = windowMembership(NetworkBurstDetected.timeStamp{idx,idx_ch}, spikes(i,2), spikes(i,3), nextStart(ch), 0);
            end            
                       
            if spikes_total > 0
                aux_spikes = aux_spikes + spikes_total;                     % total number of spikes in the bin i (cumulative across all clusters)
                aux_actCh = aux_actCh + 1;                                  % total number of active neurons in the bin i
            end   
            clear spikes_total
        end

        spikes(i,1) = aux_spikes;
        spikes(i,5) = aux_actCh;
        clear aux_actCh aux_spikes
    end
    popFiring{k} = spikes;
    [~, idx_peak] = max(spikes(:,5));
    peak_burst(k) = spikes(idx_peak,4);
    clear spikes

    aux = ini-peak_burst(k);
    if aux < left_burst
        left_burst = aux;
    end
    aux = fin-peak_burst(k);
    if aux > right_burst
        right_burst = aux;
    end
end
    
NetworkBurstStructure.populationFiring = popFiring;

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%     Bin signal from individual neurons

nbin_left = ceil(abs(left_burst)/BIN_NEURON);
nbin_right = ceil(abs(right_burst)/BIN_NEURON);
nbin_total = nbin_left+nbin_right;
signalNeuron = zeros(nPartNeu,nbin_total,5);                                % 1, midpoint of the bin i (relative to the peak of the burst), in msec
                                                                            % 2, total number of spikes in bin i (cumulative across all burst events)
                                                                            % 3, total number of bursts with activity in bin i
                                                                            % 4, total number of spikes in bin i, normalized to the total number of spikes across all bin            
                                                                            % 5, total number of spikes in bin i, normalized to the peak value

% (revised October 2026) the spikes of each neuron are taken from its whole spike train ("spikeTrain(idx_ch).timeStamp"), but only between the
% end of the previous event and the start of the next one (primary or secondary), so the activity of the neighbouring events is not counted.
% Before, they were taken from "NetworkBurstDetected.timeStamp", which only contains the spikes within the extraction window of each event 
% (from 0.4*duration before to 0.8*duration after it): the bins of the common grid outside that window counted as 0 spikes (45% of the bins 
% on the reference recording), which made the tail too early. For each event, only the bins with data are counted; the counts of each bin are 
% then scaled to the total number of events (nBurst/coverage), so the thresholds below remain proportions of the events.
all_start = [NetworkBurstDetected.IndivBurst.start];                        % start of all the primary events, in sec
all_last = [NetworkBurstDetected.IndivBurst.last];                          % end of all the primary events, in sec
if isfield(NetworkBurstDetected, 'Secondary') && isfield(NetworkBurstDetected.Secondary, 'nBurst') && NetworkBurstDetected.Secondary.nBurst > 0
    all_start = [all_start, NetworkBurstDetected.Secondary.IndivBurst.start];   % and of all the secondary events
    all_last = [all_last, NetworkBurstDetected.Secondary.IndivBurst.last];
end
all_start = all_start/K_MSEC_SEC;       all_last = all_last/K_MSEC_SEC;     % in msec

bin_ini = nan(nBurst, nbin_total);      bin_fin = nan(nBurst, nbin_total); % left and right side of the bin i of the event k, in msec
covered = false(nBurst, nbin_total);                                        % =true, if the bin i of the event k is within the data window of the event
for k=1:nBurst
    idx = idx_event(k);
    ini_k = NetworkBurstDetected.IndivBurst(idx).start/K_MSEC_SEC;          % start of the event k, in msec
    fin_k = NetworkBurstDetected.IndivBurst(idx).last/K_MSEC_SEC;           % end of the event k, in msec
    others = true(size(all_start));     others(idx) = false;                % all the other events (primary and secondary)
    data_ini = max([-Inf, all_last(others & all_last <= ini_k)]);           % end of the previous event, in msec
    data_fin = min([Inf, all_start(others & all_start >= fin_k)]);          % start of the next event, in msec
    for i=1:nbin_total                                                      % across all bins 
        bin_ini(k,i) = peak_burst(k) - (nbin_left-i+0.5)*BIN_NEURON;        % left side of the bin i, in msec
        bin_fin(k,i) = bin_ini(k,i) + BIN_NEURON;                           % right side of the bin i, in msec
    end
    covered(k,:) = bin_ini(k,:) >= data_ini & bin_fin(k,:) <= data_fin;
end
coverage = sum(covered, 1);                                                 % number of events with data in each bin
for i=1:nbin_total
    signalNeuron(:,i,1) = (bin_fin(nBurst,i)+bin_ini(nBurst,i))/2 - peak_burst(nBurst);    % midpoint of the bin i (relative to the peak of the burst), in msec
end

for ch=1:nPartNeu
    idx_ch = units_participant(ch);                                         % index of the channel/neuron ch
    spikes = spikeTrain(idx_ch).timeStamp(:);                               % whole spike train of the neuron ch, in msec
    n_spikes = count_below(spikes, bin_fin(:), 0) - count_below(spikes, bin_ini(:), 0);    % number of spikes within [ini, fin) of each bin of each event
    n_spikes = reshape(n_spikes, nBurst, nbin_total);
    n_spikes(~covered) = 0;                                                 % only the bins with data
    signalNeuron(ch,:,2) = sum(n_spikes, 1);                                % total number of spikes in the bin i (cumulative across all burst events)
    signalNeuron(ch,:,3) = sum(n_spikes > 0, 1);                            % total number of bursts with activity in bin i
end
scale = zeros(1, nbin_total);
scale(coverage > 0) = nBurst ./ coverage(coverage > 0);                     % scaled to the total number of events (=0 for the bins without data)
signalNeuron(:,:,2) = signalNeuron(:,:,2) .* scale;
signalNeuron(:,:,3) = signalNeuron(:,:,3) .* scale;
NetworkBurstStructure.coverage = coverage;

for ch=1:nPartNeu
    total = sum(signalNeuron(ch,:,2));
    height = max(signalNeuron(ch,:,2));
    signalNeuron(ch,:,4) = signalNeuron(ch,:,2)/total;
    signalNeuron(ch,:,5) = signalNeuron(ch,:,2)/height;
end

NetworkBurstStructure.neuronFiring = signalNeuron;

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%     Cross-Correlation between spike trains

Correlation = corrcoef(signalNeuron(:,:,2)');
colvect = Correlation(find(~tril(ones(size(Correlation)))));
avg_correlation = mean(abs(colvect), 'omitnan');                            % (revised October 2026: 'omitnan'; a unit without spikes made it NaN)

NetworkBurstStructure.correlation = avg_correlation;

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%     Look for the onset and tail for each neuron

onset = zeros(nPartNeu,1);
structure = nan(nPartNeu, 4);

threshold = THRESHOLD_ACT*nBurst;
threshold_twin = THRESHOLD_ACT_TWIN*nBurst;
twin=0;

if nBurst>0

    for ch=1:nPartNeu
        detected = 0;
        bin = 1;
    
        while detected==0 && bin<nbin_total
            if signalNeuron(ch,bin,3) >= threshold
                onset(ch) = bin;
                detected = 1;
            elseif signalNeuron(ch,bin,3) >= threshold_twin && signalNeuron(ch,bin+1,3) >= threshold_twin
                onset(ch) = bin+1;
                detected = 1;
                twin = twin + 1;
            end
            bin = bin + 1; 
        end
    end
    [aux_delay, aux_order] = sort(onset);
    aux_delay = unique(aux_delay);
    aux_delay(find(aux_delay==0)) = [];

    for ch=1:nPartNeu
        aux = find(aux_delay==onset(ch));
        if numel(aux)
            structure(ch,1) = aux;                                          % order based on the onset (1 is the first one)
            structure(ch,2) = (onset(ch)-nbin_left-0.5)*BIN_NEURON;         % onset of the activity, in ms (relative to the peak of the burst)
        end
        [peak_value, peak_idx] = max(signalNeuron(ch,:,2));
        structure(ch,3) = (peak_idx-nbin_left-0.5)*BIN_NEURON;              % peak of the activity, in ms (relative to the peak of the burst)
        umbral = peak_value*THRESHOLD_TAIL;
        done = 0;
        tail_index=nbin_total; 
        while done==0 && tail_index>0
            if signalNeuron(ch,tail_index,2)>umbral                         % first bin, from right to left, to cross the threshold
                done=1;                                                     % (revised October 2026) stop at the crossing bin: before, one more bin was subtracted
            else                                                            %  after finding it, so the tail was reported one bin early
                tail_index = tail_index-1;
            end
        end
        structure(ch,4) = (tail_index-nbin_left-0.5)*BIN_NEURON;                 % tail of activity, in ms (relative to the peak of the burst)
        clear aux peak_value peak_idx tail_index done
    end
end

position = nan(nPartNeu,2);
for i=1:nPartNeu
    idx_ch = units_participant(i);                                 % index of the channel/neuron ch
%    idx_ch = NetworkBurstDetected.Channels(idx_ch,1);
    position(i,1) = spikeTrain(idx_ch).positionXY(1)+1;
    position(i,2) = spikeTrain(idx_ch).positionXY(2)+1;
end

NetworkBurstStructure.structure = structure;
NetworkBurstStructure.mapPosition = position;

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%     plot results

if option_plot & nBurst >= MIN_BURST_PLOT

    [~,aux_onset] = sort(structure(:,1));
    weak_index = find(isnan(structure(:,1)));
    onset_order = setdiff(aux_onset,weak_index,'stable');
    
    if numel(onset_order)>0
        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        % plot the firing rate of neurons ordered by onset (in a heatmap)
        figure;
        subplot(3,1,[1,2]);
        heatmap(signalNeuron(onset_order, 1:round(nbin_total/2),5),'Colormap',hot)
        title(sprintf('Solid-structure neurons (%g out of %g)', numel(onset_order), nPartNeu))
        subplot(3,1,3);
        histogram(structure(onset_order,2));        ylabel('Number of neurons');        xlabel('Onset relative to burst peak (ms)')

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        N_BURST = 5;        N_NEURONS = 5;          FACTOR = 0.1;
        % plot raster plot 
        list_order = unique(structure(:,1));
        list_order(isnan(list_order)) = [];
        burst_plot = min(N_BURST,nBurst);
        if burst_plot<nBurst                                                % Plot the last set of "burst_plot" events
            ini0 =  NetworkBurstDetected.IndivBurst(idx_event(nBurst-burst_plot)).start;
        else            
            ini0 =  NetworkBurstDetected.IndivBurst(idx_event(1)).start;
        end
        fin0 =  NetworkBurstDetected.IndivBurst(idx_event(end)).last;
        ini = ini0-(fin0-ini0)*FACTOR;
        fin = fin0+(fin0-ini0)*FACTOR;
        
        figure;
        idx=1;
        subplot(2,1,1)
        for i=1:numel(list_order)
            n_plot = 0; k = 1;
            while k<=nPartNeu && n_plot<N_NEURONS
                if list_order(i)==structure(k,1)
                    idx_ch = units_participant(k);
                   %idx_ch = NetworkBurstDetected.Channels(k,1);
                    signal = spikeTrain(idx_ch).timeStamp*K_MSEC_SEC ;
                    n_unit = size(signal,1);
                    plot(signal, ones(n_unit,1)+idx,'|',"MarkerEdgeColor",[0 0 0]); hold on
                    n_plot = n_plot + 1;        idx = idx + 1;      clear signal
                end
                k = k+1;
            end
        end
        set(gca, 'YDir','reverse');     ylabel('Neurons');      xlim([ini fin]);        ylim([1 idx+1]);      title('Solid temporal structure')

        contador=1;
        subplot(2,1,2)
        for k=1:nPartNeu
                if isnan(structure(k,1)) && contador<min(idx,numel(weak_index))
                    idx_ch = units_participant(k);
                   %idx_ch = NetworkBurstDetected.Channels(k,1);
                    signal = spikeTrain(idx_ch).timeStamp*K_MSEC_SEC ;
                    n_unit = size(signal,1);
                    plot(signal, ones(n_unit,1)+contador,'|',"MarkerEdgeColor",[0 0 0]);    hold on;        clear signal
                   contador = contador + 1;
                end
        end
        ylabel('Neurons');      xlabel('Time (sec)');       xlim([ini fin]);        title('Weak temporal structure')

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        MATRIX_SIZE = 64;
        % plot the electrode map
        map = nan(MATRIX_SIZE,MATRIX_SIZE); 
        for i=1:numel(onset_order)
            pos_x = position(onset_order(i),1);
            pos_y = position(onset_order(i),2);
            map(pos_x,pos_y) = structure(onset_order(i),1);
        end
        figure;
        heatmap(map,'XDisplayLabels',NaN*ones(size(map,1),1),'YDisplayLabels',NaN*ones(size(map,1),1),'Colormap',jet);
        % heatmap(map,'XDisplayLabels',NaN*ones(size(map,1),1),'YDisplayLabels',NaN*ones(size(map,1),1),'Colormap',jet,'ColorLimits',[-4 4]);    
    else
        fprintf("\n NO burst has a robust temporal structure!!! \n")
    end
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
else
    NetworkBurstStructure.populationFiring = [];       
    NetworkBurstStructure.neuronFiring = [];
    NetworkBurstStructure.structure = []; 
    NetworkBurstStructure.mapPosition = [];
    NetworkBurstStructure.correlation = [];
end

end
